{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.rolling_30_days_dashboard AS WITH capsule_launch AS ( SELECT CAPSULE, LAUNCH_DATE FROM VALUES (\'Street FC\', \'2026-06-23\'::DATE), (\'Street FC Plus\', \'2026-06-23\'::DATE), (\'botanical THEME\', \'2026-07-11\'::DATE), (\'Embroided Shirts\', \'2026-07-16\'::DATE), (\'GOLF POLO THEME\', \'2026-07-27\'::DATE), (\'PHOTO PRINT\', \'2026-08-06\'::DATE), (\'Try Less Denim\', \'2026-08-14\'::DATE), (\'Festive - 1\', NULL), (\'Printed Shirts\', \'2026-09-04\'::DATE), (\'Luxe\', \'2026-09-18\'::DATE) AS t(CAPSULE, LAUNCH_DATE) ), sku_mapping AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU, TRIM(COLLECTION) AS COLLECTION FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL ), last_30_days AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, c.COLLECTION AS CAPSULE, cl.LAUNCH_DATE, SUM(h.GROSS_QUANTITY) AS LAST_30_QTY, SUM(h.GROSS_SALES) AS LAST_30_GROSS_SALES, SUM(h.DISCOUNT_AMOUNT) AS LAST_30_DISCOUNT, ROUND( SUM(h.GROSS_SALES) / NULLIF( SUM(h.GROSS_QUANTITY), 0 ), 2 ) AS LAST_30_ASP FROM snitch_db.maplemonk.horizontal_sales_categories h INNER JOIN sku_mapping c ON UPPER(TRIM(h.SKU_GROUP)) = UPPER(TRIM(c.SKU)) LEFT JOIN capsule_launch cl ON LOWER(TRIM(c.COLLECTION)) = LOWER(TRIM(cl.CAPSULE)) WHERE TO_DATE(h.DATE) >= CURRENT_DATE() - 30 GROUP BY UPPER(TRIM(h.SKU_GROUP)), c.COLLECTION, cl.LAUNCH_DATE ), first_sales AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MIN(DATE) AS FIRST_SALE_DATE FROM snitch_db.maplemonk.horizontal_sales_categories WHERE GROSS_QUANTITY > 0 GROUP BY 1 ), sales_periods AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, SUM( CASE WHEN h.DATE >= fs.FIRST_SALE_DATE THEN h.GROSS_QUANTITY ELSE 0 END ) AS CUMULATIVE_SALES_QTY, SUM( CASE WHEN cl.LAUNCH_DATE IS NOT NULL AND h.DATE >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END ) AS LAUNCH_TO_DATE_SALES_QTY FROM snitch_db.maplemonk.horizontal_sales_categories h INNER JOIN first_sales fs ON UPPER(TRIM(h.SKU_GROUP)) = fs.SKU_GROUP INNER JOIN sku_mapping sm ON UPPER(TRIM(h.SKU_GROUP)) = sm.SKU LEFT JOIN capsule_launch cl ON LOWER(TRIM(sm.COLLECTION)) = LOWER(TRIM(cl.CAPSULE)) GROUP BY 1 ), inwards AS ( SELECT sku_group, SUM(inward_qty) AS TOTAL_INWARD_QTY FROM ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX( \'-\', REVERSE(\"Item Type skuCode\") ) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS sku_group, PUTAWAY_UPDATED::DATE AS inward_date, SUM( PUTAWAY_COMPLETED_QUANTITY ) AS inward_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1, 2 ) GROUP BY sku_group ), rolling_30_metrics AS ( SELECT l.SKU_GROUP, l.CAPSULE, l.LAUNCH_DATE, l.LAST_30_QTY, l.LAST_30_GROSS_SALES, l.LAST_30_DISCOUNT, l.LAST_30_ASP, i.TOTAL_INWARD_QTY, fs.FIRST_SALE_DATE, sp.CUMULATIVE_SALES_QTY, sp.LAUNCH_TO_DATE_SALES_QTY, DATEDIFF( DAY, fs.FIRST_SALE_DATE, CURRENT_DATE() ) AS DAYS_ACTIVE, DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) AS DAYS_SINCE_LAUNCH, ROUND( ( sp.CUMULATIVE_SALES_QTY / NULLIF( i.TOTAL_INWARD_QTY, 0 ) ) * 100, 2 ) AS STR_PERCENT_SOLD, CASE WHEN l.LAUNCH_DATE IS NULL THEN NULL WHEN DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN ROUND( ( sp.LAUNCH_TO_DATE_SALES_QTY / NULLIF( i.TOTAL_INWARD_QTY, 0 ) ) * 100, 2 ) ELSE ROUND( ( l.LAST_30_QTY / NULLIF( i.TOTAL_INWARD_QTY, 0 ) ) * 100, 2 ) END AS LAST_30_STR, CASE WHEN l.LAUNCH_DATE IS NULL THEN NULL WHEN DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) = 0 THEN NULL WHEN DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) < 30 THEN LEAST( ROUND( ( sp.LAUNCH_TO_DATE_SALES_QTY / NULLIF( i.TOTAL_INWARD_QTY, 0 ) ) * ( 30.0 / DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) ) * 100, 2 ), 100 ) ELSE ROUND( ( l.LAST_30_QTY / NULLIF( i.TOTAL_INWARD_QTY, 0 ) ) * 100, 2 ) END AS NORMALIZED_30_STR FROM last_30_days l LEFT JOIN inwards i ON UPPER(TRIM(l.SKU_GROUP)) = UPPER(TRIM(i.SKU_GROUP)) LEFT JOIN first_sales fs ON UPPER(TRIM(l.SKU_GROUP)) = fs.SKU_GROUP LEFT JOIN sales_periods sp ON UPPER(TRIM(l.SKU_GROUP)) = sp.SKU_GROUP ) SELECT r30.*, r30.LAST_30_STR AS STR, CASE WHEN LOWER(TRIM(r30.CAPSULE)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\' ) THEN \'YES\'; ELSE \'NO\' END AS FOCUS_CAPSULE FROM rolling_30_metrics r30 ORDER BY LAST_30_GROSS_SALES DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            